exercises.solution:
const students = [{ id: 1, name: "Ava" }, { id: 2, name: "Ben" }];
const enrollments = [
  { student_id: 1, course: "C211" },
  { student_id: 9, course: "C250" },
];
function innerJoin() {
  const rows = [];
  for (const e of enrollments) {
    const s = students.find(s => s.id === e.student_id);
    if (s) rows.push({ name: s.name, course: e.course });
  }
  return rows;
}
console.log(innerJoin());

