const students = [{ id: 1, name: "Ava" }, { id: 2, name: "Ben" }];
const enrollments = [{ student_id: 1, course: "C211" }];
function leftJoin() {
  return students.map(s => {
    const e = enrollments.find(e => e.student_id === s.id);
    return { name: s.name, course: e ? e.course : null };
  });
}
console.log(leftJoin());

