const students = [{ id: 1 }, { id: 2 }];
const enrollments = [{ student_id: 1 }, { student_id: 9 }];
function checkFK() {
  return enrollments
    .map(e => e.student_id)
    .filter(id => !students.some(s => s.id === id));
}
console.log(checkFK());
